  1	"""
  2	Turn the page a worker is on into compact text for the model, with refs for everything it can act on.
  3	
  4	What a person would see, not the raw DOM: hidden elements are dropped (decoy text and injected instructions are
  5	usually `hidden` or `aria-hidden`), collapsed `<details>` are opened, tooltips and canvas/img labels are inlined,
  6	same-origin iframes are walked in place and zero-width characters are stripped. Interactive elements get a
  7	`data-ar` ref such as `e12` that `locate` resolves again for clicking and filling.
  8	"""
  9	from playwright.async_api import Frame, Locator, Page
 10	
 11	WALK_JS = r"""
 12	([start, stamp]) => {
 13	  const ZW = /[​‌‍⁠﻿­]/g;
 14	  const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
 15	  const SKIP = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'HEAD', 'META', 'LINK']);
 16	  const BLOCK = /^(block|flex|grid|table|table-row|list-item|flow-root|table-caption)$/;
 17	  const ROLES = new Set(['button', 'link', 'tab', 'menuitem', 'option', 'checkbox', 'radio', 'switch', 'combobox',
 18	                         'slider', 'REDACTED', 'searchbox']);
 19	  let n = start;
 20	  const out = [];
 21	  const crossOrigin = [];
 22	  const emit = s => out.push(s);
 23	
 24	  function isHidden(el, win) {
 25	    if (el.hidden || el.getAttribute('aria-hidden') === 'true' || el.inert) return true;
 26	    const cs = win.getComputedStyle(el);
 27	    return cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse';
 28	  }
 29	  function textOnly(node) {  // a label's own words, without the controls and styles it wraps
 30	    const copy = node.cloneNode(true);
 31	    copy.querySelectorAll('select,option,input,textarea,button,style,script').forEach(e => e.remove());
 32	    return copy.textContent;
 33	  }
 34	  function labelOf(el) {
 35	    const own = el.getAttribute('aria-label');
 36	    if (own) return clean(own);
 37	    const by = el.getAttribute('aria-labelledby');
 38	    if (by) {
 39	      const t = by.split(/\s+/).map(id => el.ownerDocument.getElementById(id)).filter(Boolean)
 40	        .map(e => e.textContent).join(' ');
 41	      if (clean(t)) return clean(t);
 42	    }
 43	    if (el.labels && el.labels.length) {
 44	      const t = clean(Array.from(el.labels).map(textOnly).join(' '));
 45	      if (t) return t;
 46	    }
 47	    return clean(el.getAttribute('title') || el.getAttribute('placeholder') || el.getAttribute('name') || '');
 48	  }
 49	  function isInteractive(el) {
 50	    const tag = el.tagName;
 51	    if (tag === 'A' && el.hasAttribute('href')) return true;
 52	    if (tag === 'BUTTON' || tag === 'SELECT' || tag === 'TEXTAREA') return true;
 53	    if (tag === 'SUMMARY') return el.hasAttribute('onclick');  // details are always shown open
 54	    if (tag === 'INPUT') return el.type !== 'hidden';
 55	    const role = el.getAttribute('role');
 56	    return !!(role && ROLES.has(role)) || el.hasAttribute('onclick');
 57	  }
 58	  function ref(el) { const r = 'e' + (n++); el.setAttribute('data-ar', r); return r; }
 59	
 60	  function describe(el) {
 61	    const r = ref(el);
 62	    const tag = el.tagName;
 63	    const dis = el.disabled ? ' disabled' : '';
 64	    if (tag === 'A') {
 65	      const name = clean(el.innerText) || labelOf(el);
 66	      return `[${r} link "${name}" -> ${el.getAttribute('href')}]`;
 67	    }
 68	    if (tag === 'SELECT') {
 69	      const opts = Array.from(el.options);
 70	      const sel = opts.filter(o => o.selected).map(o => clean(o.textContent)).join(', ');
 71	      let list = opts.slice(0, 60).map(o => clean(o.textContent) + (o.disabled ? ' (disabled)' : '')).join(' | ');
 72	      if (opts.length > 60) list += ` | ... ${opts.length - 60} more`;
 73	      return `[${r} select "${labelOf(el)}" selected="${sel}"${dis} options: ${list}]`;
 74	    }
 75	    if (tag === 'TEXTAREA') return `[${r} textarea "${labelOf(el)}" value="${clean(el.value)}"${dis}]`;
 76	    if (tag === 'INPUT') {
 77	      const t = (el.type || 'text').toLowerCase();
 78	      if (t === 'checkbox' || t === 'radio')
 79	        return `[${r} ${t} "${labelOf(el)}"${el.checked ? ' checked' : ' unchecked'}${dis}]`;
 80	      if (t === 'range')
 81	        return `[${r} slider "${labelOf(el)}" value=${el.value} min=${el.min || 0} max=${el.max || 100}${dis}]`;
 82	      if (t === 'submit' || t === 'button' || t === 'reset' || t === 'image')
 83	        return `[${r} button "${clean(el.value) || labelOf(el)}"${dis}]`;
 84	      const kind = t === 'password' ? 'password' : 'REDACTED';
 85	      const value = t === 'password' ? (el.value ? '***' : '') : clean(el.value);
 86	      const ph = el.placeholder ? ` placeholder="${clean(el.placeholder)}"` : '';
 87	      return `[${r} ${kind} "${labelOf(el)}" value="${value}"${ph}${el.required ? ' required' : ''}${dis}]`;
 88	    }
 89	    const role = el.getAttribute('role') || tag.toLowerCase();
 90	    const name = clean(el.innerText) || labelOf(el);
 91	    const state = el.getAttribute('aria-expanded') ? ` expanded=${el.getAttribute('aria-expanded')}` : '';
 92	    return `[${r} ${role} "${name}"${state}${dis}]`;
 93	  }
 94	
 95	  function walkDoc(doc, win) {
 96	    doc.querySelectorAll('[data-ar]').forEach(e => e.removeAttribute('data-ar'));
 97	    doc.querySelectorAll('details:not([open])').forEach(d => { d.open = true; });
 98	    doc.documentElement.dataset.arWalked = stamp;
 99	    if (doc.body) walk(doc.body, win);
100	  }
101	
102	  function walk(node, win) {
103	    for (const child of node.childNodes) {
104	      if (child.nodeType === 3) {
105	        const raw = child.nodeValue.replace(ZW, '');
106	        const pre = /^pre/.test(win.getComputedStyle(node).whiteSpace);  // keep the lines of files and tables
107	        const t = pre ? raw.replace(/[ \t]+/g, ' ').replace(/\n/g, '\u2028') : raw.replace(/\s+/g, ' ');
108	        if (t.trim()) emit(t);
109	        continue;
110	      }
111	      if (child.nodeType !== 1) continue;
112	      const el = child;
113	      if (SKIP.has(el.tagName)) continue;
114	      const role = el.getAttribute('role');
115	      if (role === 'tooltip') {
116	        if (!el.hidden && el.getAttribute('aria-hidden') !== 'true') emit(` (tooltip: ${clean(el.textContent)}) `);
117	        continue;
118	      }
119	      if (isHidden(el, win)) continue;
120	      const tag = el.tagName;
121	      if (tag === 'CANVAS' || tag === 'IMG' || tag === 'svg' || tag === 'SVG' || role === 'img') {
122	        const label = clean(el.getAttribute('aria-label') || el.getAttribute('alt') || el.getAttribute('title'));
123	        if (label) emit(` [img: ${label}] `);
124	        continue;
125	      }
126	      if (tag === 'IFRAME' || tag === 'FRAME') {
127	        const src = el.getAttribute('src') || '';
128	        let inner = null;
129	        try { inner = el.contentDocument; } catch (e) { inner = null; }
130	        if (inner && inner.body) {
131	          emit(`\n[frame ${src}]\n`);
132	          walkDoc(inner, el.contentWindow);
133	          emit(`\n[/frame]\n`);
134	        } else {
135	          crossOrigin.push(src);
136	          emit(`\n[frame ${src} (separate)]\n`);
137	        }
138	        continue;
139	      }
140	      const cs = win.getComputedStyle(el);
141	      const block = BLOCK.test(cs.display) || /^H[1-6]$/.test(tag) || tag === 'BR';
142	      if (block) emit('\n');
143	      if (/^H[1-6]$/.test(tag)) emit('#'.repeat(+tag[1]) + ' ');
144	      if (cs.display === 'list-item') emit('- ');
145	      if (isInteractive(el)) {
146	        emit(' ' + describe(el) + ' ');
147	        // a label or summary may wrap further controls; walk those, not the text again
148	        el.querySelectorAll('input,select,textarea,button').forEach(inner => {
149	          if (inner !== el && !isHidden(inner, win)) emit(' ' + describe(inner) + ' ');
150	        });
151	      } else {
152	        walk(el, win);
153	        if (tag === 'TIME' && el.getAttribute('datetime')) emit(` (datetime=${el.getAttribute('datetime')})`);
154	        const title = el.getAttribute('title');
155	        if (title && !clean(el.textContent).includes(clean(title))) emit(` (title: ${clean(title)})`);
156	      }
157	      if (cs.display === 'table-cell') emit(' | ');
158	      if (block) emit('\n');
159	    }
160	  }
161	
162	  walkDoc(document, window);
163	  const text = out.join('')
164	    .replace(/[ \t]+/g, ' ')
165	    .replace(/ *\n */g, '\n')
166	    .replace(/\n{2,}/g, '\n')
167	    .replace(/\u2028/g, '\n')
168	    .trim();
169	  return {text, next: n, crossOrigin};
170	}
171	"""
172	
173	
174	async def observe(page: Page, stamp: str = "1") -> str:
175	    """The page's visible content as text with `[eN ...]` refs; frames the main walk could not enter follow."""
176	    result = await page.main_frame.evaluate(WALK_JS, [1, stamp])
177	    parts = [result["text"]]
178	    next_id = result["next"]
179	    if result["crossOrigin"]:
180	        for frame in page.frames[1:]:
181	            try:
182	                walked = await frame.evaluate("document.documentElement.dataset.arWalked || ''")
183	                if walked == stamp:
184	                    continue
185	                sub = await frame.evaluate(WALK_JS, [next_id, stamp])
186	            except Exception:
187	                continue
188	            next_id = sub["next"]
189	            parts.append(f"[frame {frame.url}]\n{sub['text']}\n[/frame]")
190	    return "\n".join(parts)
191	
192	
193	async def locate(page: Page, ref: str) -> Locator | None:
194	    """The element a ref from the latest `observe` points at, in whichever frame it lives."""
195	    selector = f'[data-ar="{ref.strip()}"]'
196	    frames: list[Frame] = [page.main_frame, *page.frames[1:]]
197	    for frame in frames:
198	        try:
199	            locator = frame.locator(selector)
200	            if await locator.count():
201	                return locator.first
202	        except Exception:
203	            continue
204	    return None

